contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 recordedBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = address(this).balance;
        uint256 cBefore = address(c).balance;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint256 recordedAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientAfter = address(this).balance;
        uint256 cAfter = address(c).balance;

        assert(recordedAfter == 0 && recipientAfter == recipientBefore + recordedBefore && cAfter == cBefore - recordedBefore);
    }

    receive() external payable {}
}

