pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 recordedBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint256 recipientBefore = address(this).balance;
        uint256 cBefore = address(c).balance;
        try c.withdrawBalance() {} catch { return; }
        uint256 recordedAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        uint256 recipientAfter = address(this).balance;
        uint256 cAfter = address(c).balance;
        assertTrue(recordedAfter == 0 && recipientAfter == recipientBefore + recordedBefore && cAfter == cBefore - recordedBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
